<?php
ini_set('memory_limit','1024M');$root=realpath($argv[1]);chdir($root);require $root.'/plugins/autoloader.php';
use libspech\Rtp\MediaChannel;use Swoole\Coroutine as Co;
Co\run(function(){ $s=new SocketMutable(AF_INET,SOCK_DGRAM,SOL_UDP);$s->bind('127.0.0.1',0);$tx=new SocketMutable(AF_INET,SOCK_DGRAM,SOL_UDP);$tx->bind('127.0.0.1',0);$d=new SocketMutable(AF_INET,SOCK_DGRAM,SOL_UDP);$d->bind('127.0.0.1',0);$m=new MediaChannel($s,'ptime-wire');$m->setSettings(['sendSilenceProbeToMembers'=>false]);foreach([$tx,$d] as $sock)$m->addMember(['address'=>'127.0.0.1','port'=>$sock->getsockname()['port'],'codec'=>'PCMA','pt'=>8,'frequency'=>8000,'ptime'=>20]);$m->start();$packets=[];for($i=0;$i<2;$i++){$tx->sendto('127.0.0.1',$s->getsockname()['port'],pack('CCnNN',128,8,$i,320*$i,42).str_repeat(chr(213),320));$peer=[];$packets[]=$d->recvfrom($peer,.2);} $a=unpack('Cfirst/Csecond/nseq/Nts',substr($packets[0],0,8));$b=unpack('Cfirst/Csecond/nseq/Nts',substr($packets[1],0,8));echo json_encode(['payload_bytes'=>strlen($packets[0])-12,'timestamp_delta'=>($b['ts']-$a['ts'])&0xffffffff,'expected_samples_from_payload'=>320])."\n";$m->close();Co::sleep(.02);$tx->close();$d->close();});
